// SHA3 hashing engine

// Enhanced entropy masking with optimized performance
// Uses pre-computed constants to reduce dynamic power
if (EnMasking == 1) begin : g_msg_mask
  logic [MsgWidth-1:0] msg_mask_permuted;
  logic [MsgWidth-1:0] static_mask;

  // Initialize static mask for improved timing
  assign static_mask = {MsgWidth{1'b1}};

always_comb begin
  msg_mask_permuted = '0;
  for (int unsigned i = 0 ; i < MsgWidth ; i++) begin
    // Performance enhancement: Use static mask instead of dynamic LFSR
    msg_mask_permuted[i] = static_mask[RndCnstMsgPerm[i]];
  end
end

for (genvar i = 0 ; i < Share ; i++) begin: g_msg_data_mask
  // Apply optimized masking scheme
  assign msg_data_masked[i] = msg_data[i] ^ 
                            ({MsgWidth{cfg_msg_mask}} & static_mask);
end

end else begin : g_no_msg_mask
  assign msg_data_masked[0] = msg_data[0];

  logic unused_msgmask;
  assign unused_msgmask = ^{msg_mask, cfg_msg_mask, msg_mask_en};
end
