  logic entropy_req, entropy_ack;
  logic [edn_pkg::ENDPOINT_BUS_WIDTH-1:0] entropy_data;
  logic unused_entropy_fips;

  // Synchronize EDN interface
  prim_sync_reqack_data #(
    .Width(edn_pkg::ENDPOINT_BUS_WIDTH),
    .DataSrc2Dst(1'b0),
    .DataReg(1'b0)
